// pubspec.yaml: provider: ^6.1.1
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

// ────── View model ──────
class CounterVM extends ChangeNotifier {
  int _n = 0;
  int get n => _n;
  void inc() { _n++; notifyListeners(); }
  @override void dispose() { /* free timers, subscriptions */ super.dispose(); }
}

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) {
    // ────── MultiProvider mounts app-level DI at root ──────
    return MultiProvider(
      providers: [
        Provider<ApiClient>(create: (_) => ApiClient()),        // immutable
        ChangeNotifierProvider(create: (_) => CounterVM()),      // mutable
        ProxyProvider<ApiClient, UserRepository>(               // derived
          update: (_, api, prev) => UserRepository(api),
        ),
      ],
      child: MaterialApp(home: const Home()),
    );
  }
}

class Home extends StatelessWidget {
  const Home({super.key});
  @override
  Widget build(BuildContext context) {
    // watch<T>() subscribes; rebuild on notifyListeners()
    final vm = context.watch<CounterVM>();
    return Scaffold(
      appBar: AppBar(title: const Text('Counter')),
      body: Center(child: Text('${vm.n}', style: const TextStyle(fontSize: 48))),
      floatingActionButton: FloatingActionButton(
        // read<T>() does NOT subscribe — perfect for event handlers.
        onPressed: () => context.read<CounterVM>().inc(),
        child: const Icon(Icons.add),
      ),
    );
  }
}

// 1. watch<T> — subscribe; rebuild on ANY change of T.
final cart = context.watch<Cart>();
Text('${cart.items.length} items');   // this Text rebuilds on any Cart change

// 2. read<T> — no subscription; used in callbacks (onTap) or initState.
ElevatedButton(
  onPressed: () => context.read<Cart>().add(item),  // won't cause the button to rebuild
  child: const Text('Add'),
)

// 3. select<T, R> — subscribe to a slice; rebuild only when the slice changes.
final count = context.select<Cart, int>((c) => c.items.length);
Text('$count items');   // rebuilds only when the count changes, not on price change

// 4. Consumer<T> — same as watch but scopes the rebuild boundary.
Consumer<Cart>(
  builder: (context, cart, _) => Badge(count: cart.items.length),
);

// 5. Selector<A, R> — the widget-form of select.
Selector<Cart, int>(
  selector: (_, c) => c.items.length,
  builder: (context, count, _) => Text('$count'),
);
